class saveFile {
    constructor(name, data) {
        this.name = name
        this.key = "saveFile_" + name;
        this.globalInfos = data  
    }
    
    static LOCAL_STORAGE_LIMIT = 5 * 1024 * 1024

    static getDefaultInfos() { 
        const rawData = JSON.parse(defaultSaveFileString);
        let restoredData = restoreClasses(rawData);
        return restoredData     
    }

    static getCurrentInfos() {
        //Değiştirmek istersen bu kısımı kullan
        const currents = {} 
        for (const key in Registry) {
            currents[key] = cloneAnyObject(Registry[key].get());
        }
        return currents;
    }

    save() {
        this.globalInfos = {};
        for (const key in Registry) {
            this.globalInfos[key] = cloneAnyObject(Registry[key].get());
        }

         if (!this.canSave()) {
            console.log("Not Enough Memory!");
            return false;
        }

        try {
            const json = JSON.stringify(this.globalInfos);
            localStorage.setItem(this.key, json);
        } catch (err) {
            console.error("Error while saving to localStorage:", err);
        }
    }

    load() {
        for (const key in this.globalInfos) {
            if(Registry[key] == undefined) {console.log("Bu Key yok!: " + key);continue}
            Registry[key].set(cloneAnyObject(this.globalInfos[key]));
        }

        getGateNames()

        //Creates the visualObjects in savedGates
        for(let n of gateNames) {
            if(!include(defaultGates, n)) {
                createVisualObjects(gateInfos[n].savedGate) 
                findCorrectState(n) 
            }  
        }
        
        function createVisualObjects(tempObjects) {
            let tempGates = tempObjects.filter(obj=> obj.ObjectName == "Gate")
            for(let obj of tempGates) {
                if(!include(defaultGates, obj.name)) {
                    obj.visualObjects = obj.createVisualObjects()  //Not this function gates' function
                    if(gateInfos[obj.name].isMemoryHolder) {
                        obj.memory = undefined            
                    } 
                   
                          
                }		
            }
            for(let obj of tempGates) {
                if(include(!defaultGates, obj.name)) {
                    createVisualObjects(obj.visualObjects)
                }		
            }     
        }
        function findCorrectState(objects, gate) {
            // Sets the 
            
        }
        ////////////////

        fastProcessedGates = []
        fastProcessInfos = {}
        if(doFastProcess && 1) {
             for(let n of gateNames) {
                if(gateInfos[n].savedGate != undefined) {
                    if(gateInfos[n].isFastProcessed) {	
                        fastProcessQueue.push(n)			
                    }
                }
            }
        }
       
        if(this.name == "test") debugD()
    }

    update() {
        for(const key in Registry) {
            if(!this.globalInfos.hasOwnProperty(key)) {
                this.globalInfos[key] = cloneAnyObject(Registry[key].get());
                console.log(`${this.name} adlı dosyaya şu eklendi: ${key}`);
            }
        }

        for(const key in this.globalInfos) {
            if(!Registry.hasOwnProperty(key)) {
               delete this.globalInfos[key]
               console.log(`${this.name} adlı dosyadan şu silindi: ${key}`)
            }
        }

        this.save();
    }

    static updateAllFiles() {
        for(let s of saveFiles) {
            s.update()
        }
    }

    delete() {
        localStorage.removeItem(this.key);

        Splice(fileNames, this.name)
        Splice(saveFiles, this)

        console.log(
            `%c[Deleted] %c${this.key}`,
            "color: #F44; font-weight: bold;",
            "color: pink;"
        );  
    }

    rename(newName) {
        const newKey = "saveFile_" + newName;
        const data = localStorage.getItem(this.key);
        if (data !== null) {
            localStorage.removeItem(this.key);
            localStorage.setItem(newKey, data);
        }

        Splice(fileNames, this.name)
        this.name = newName;

        console.log(`File renamed: ${this.key} → ${newKey}`);
        return true;
    }

    duplicate(name) {
        const newData = cloneAnyObject(this.globalInfos);
        const newFile = new saveFile(name, newData);
        saveFiles.push(newFile);
        fileNames.push(name);
        localStorage.setItem("saveFile_" + name, JSON.stringify(newData));
        console.log(`File duplicated: ${this.name} → ${name}`);
        return newFile;
    }

    static createNewFile(name) {
        if(typeof name != "string") {
            console.log("Hata!")
            return
        }
        const defaultData = this.getDefaultInfos(); 
        const file = new saveFile(name, defaultData);
        saveFiles.push(file);
        fileNames.push(name);
        localStorage.setItem("saveFile_" + name, JSON.stringify(defaultData));
        console.log("Yeni savefile oluşturuldu:", name);
    }

    static deleteAllFiles() {
        for(let L = saveFiles.length - 1; L >= 0; L--) {
            saveFiles[L].delete()
        }
    }

    getFileSize() {
        const key = "saveFile_" + this.name;
        const data = localStorage.getItem(key);

        if (!data) {
            console.log("Dosya localStorage'da yok.");
            return;
        }

        const bytes = new Blob([data]).size;
        const kb = (bytes / 1024).toFixed(2);
        const mb = (bytes / 1024 / 1024).toFixed(4);

        console.log(`File: ${this.name} | ${kb} KB (${mb} MB)`);
    }

    

    canSave() {
        const newData = JSON.stringify(saveFile.getCurrentInfos());
        const newSize = new Blob([newData]).size;

        const oldData = localStorage.getItem(this.key);
        const oldSize = new Blob([oldData]).size;

        const usedSize = getLocalStorageTotalBytes()

        const projected = usedSize - oldSize + newSize;

        return projected < saveFile.LOCAL_STORAGE_LIMIT;
    }
}

function getLocalStorageTotalBytes() {
    let total = 0;

    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        const value = localStorage.getItem(key);
        total += new Blob([value]).size;
    }

    return total;
}

